static uint64_t AllocateGpuDeviceEpoch3D(){
 uint64_t current=NextGpuDeviceEpoch3D.load(std::memory_order_relaxed);
 for(;;){if(!current||current==UINT64_MAX)throw std::overflow_error("GPU device epoch space exhausted");if(NextGpuDeviceEpoch3D.compare_exchange_weak(current,current+1,std::memory_order_relaxed,std::memory_order_relaxed))return current;}
}
