static WindowPresentationState3D ObservePresentationWindow3D(HWND window){
 WindowPresentationState3D state;state.valid=IsWindow(window)!=FALSE;
 if(!state.valid)return state;
 state.visible=IsWindowVisible(window)!=FALSE;state.iconic=IsIconic(window)!=FALSE;state.foreground=GetForegroundWindow()==window;
 WINDOWPLACEMENT placement{};placement.length=sizeof(placement);state.placementValid=GetWindowPlacement(window,&placement)!=FALSE;
 if(state.placementValid)state.showCommand=placement.showCmd;
 DWORD cloaked{};const HRESULT hr=DwmGetWindowAttribute(window,DWMWA_CLOAKED,&cloaked,sizeof(cloaked));
 state.cloakedHresult=uint32_t(hr);state.cloakedValid=SUCCEEDED(hr);if(state.cloakedValid)state.cloaked=cloaked;
 return state;
}
