// 選用系統字型：字元共用原有有界快取，保留舊 Text 的點陣外觀與 ABI。
static uint32_t NextSystemUtf8(std::string_view text,size_t& index){
    const auto first=static_cast<unsigned char>(text[index]);
    const size_t length=first<128?1:(first>=0xc2&&first<=0xdf)?2:
        (first>=0xe0&&first<=0xef)?3:(first>=0xf0&&first<=0xf4)?4:0;
    if(!length||index+length>text.size())throw std::invalid_argument("System text invalid UTF8");
    uint32_t code=first&(length==1?0x7fu:length==2?0x1fu:length==3?0x0fu:7u);
    for(size_t n=1;n<length;++n){const auto byte=static_cast<unsigned char>(text[index+n]);
        if((byte&0xc0)!=0x80)throw std::invalid_argument("System text invalid UTF8 continuation");
        code=(code<<6)|(byte&0x3fu);
    }
    if((length==2&&code<0x80)||(length==3&&code<0x800)||(length==4&&code<0x10000)||
       (code>=0xd800&&code<=0xdfff)||code>0x10ffff)
        throw std::invalid_argument("System text noncanonical UTF8");
    if(code>0xffff||(code<32&&code!='\n'))
        throw std::invalid_argument("System text unsupported character");
    index+=length;return code;
}
struct SystemTextBounds2D{Vec2 minimum{},maximum{};};
static SystemTextBounds2D SystemTextBounds(std::string_view text,float pixelHeight){
    if(!std::isfinite(pixelHeight)||pixelHeight<=0||pixelHeight>256||text.size()>65536)
        throw std::invalid_argument("System text invalid size or budget");
    SystemTextBounds2D bounds;
    if(text.empty())return bounds;
    const float pixel=pixelHeight/18.f;
    const auto& reference=LoadSystemGlyph(' ');
    if(!reference.systemValid)throw std::runtime_error("System font unavailable");
    const float lineHeight=float(reference.lineHeight)*pixel;
    float penX{},penY{};bounds.maximum.y=lineHeight;
    for(size_t index=0;index<text.size();){
        const auto code=NextSystemUtf8(text,index);
        if(code=='\n'){penX=0;penY+=lineHeight;bounds.maximum.y=(std::max)(bounds.maximum.y,penY+lineHeight);continue;}
        const auto& glyph=LoadSystemGlyph(code);
        if(!glyph.systemValid)throw std::runtime_error("System glyph unavailable");
        const float left=penX+float(glyph.bearingX)*pixel;
        const float top=penY+float(glyph.ascent-glyph.originY)*pixel;
        if(!glyph.spans.empty()){
            bounds.minimum.x=(std::min)(bounds.minimum.x,left);
            bounds.minimum.y=(std::min)(bounds.minimum.y,top);
            bounds.maximum.x=(std::max)(bounds.maximum.x,left+float(glyph.width)*pixel);
            bounds.maximum.y=(std::max)(bounds.maximum.y,top+float(glyph.height)*pixel);
        }
        penX+=float(glyph.naturalAdvance)*pixel;
        bounds.maximum.x=(std::max)(bounds.maximum.x,penX);
    }
    return bounds;
}
Vec2 DrawList::MeasureSystemText(std::string_view text,float pixelHeight)const{
    const auto bounds=SystemTextBounds(text,pixelHeight);
    return bounds.maximum-bounds.minimum;
}
void DrawList::SystemText(Vec2 p,std::string_view text,float pixelHeight,Color color){
    if(!std::isfinite(p.x)||!std::isfinite(p.y)||!std::isfinite(color.r)||
       !std::isfinite(color.g)||!std::isfinite(color.b)||!std::isfinite(color.a))
        throw std::invalid_argument("System text invalid position or color");
    // 先驗證整份字串與真正墨跡邊界，避免尾端錯誤留下半份文字。
    const auto bounds=SystemTextBounds(text,pixelHeight);
    ++stats_.textContainmentTests;++stats_.totalTextContainmentTests;
    auto visibility=color.a>0?PrimitiveClipResult::Contained:PrimitiveClipResult::Culled;
    if(color.a>0&&clipEnabled_)
        visibility=ClassifyTransformedBounds(p,p+bounds.maximum-bounds.minimum);
    const auto spanQuad=[&](Vec2 center,Vec2 size,Color col){
        if(visibility==PrimitiveClipResult::Contained)SubmitContainedTextQuad(center,size,col);
        else if(visibility==PrimitiveClipResult::Culled)CullTextQuad();
        else Quad(center,size,col);
    };
    const float pixel=pixelHeight/18.f;
    const float lineHeight=float(LoadSystemGlyph(' ').lineHeight)*pixel;
    const Vec2 origin=p-bounds.minimum;
    float penX{},penY{};
    for(size_t index=0;index<text.size();){
        const auto code=NextSystemUtf8(text,index);
        if(code=='\n'){penX=0;penY+=lineHeight;continue;}
        const auto& glyph=LoadSystemGlyph(code);
        ++stats_.textGlyphs;
        stats_.textSourcePixels+=glyph.sourcePixels;stats_.totalTextSourcePixels+=glyph.sourcePixels;
        stats_.textSpans+=glyph.spans.size();stats_.totalTextSpans+=glyph.spans.size();
        for(const auto& span:glyph.spans)
            spanQuad({origin.x+penX+(float(glyph.bearingX+span.x)+float(span.length)*.5f)*pixel,
                      origin.y+penY+(float(glyph.ascent-glyph.originY+span.y)+.5f)*pixel},
                     {float(span.length)*pixel,pixel},
                     {color.r,color.g,color.b,color.a*float(span.coverage)/64.f});
        penX+=float(glyph.naturalAdvance)*pixel;
    }
}

