 void CreateMultisampleTargets() {
   if (!stats.multisampleSupported || dlss.Enabled() || msaaHdrSceneColor ||
       msaaDepth)
     return;
   D3D12_HEAP_PROPERTIES heap{};
   heap.Type = D3D12_HEAP_TYPE_DEFAULT;
   D3D12_RESOURCE_DESC desc{};
   desc.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D;
   desc.Width = width;
   desc.Height = height;
   desc.DepthOrArraySize = 1;
   desc.MipLevels = 1;
   desc.SampleDesc = {4, stats.multisampleQuality};
   desc.Layout = D3D12_TEXTURE_LAYOUT_UNKNOWN;
   desc.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
   desc.Flags = D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET;
   D3D12_CLEAR_VALUE colorClear{};
   colorClear.Format = desc.Format;
   colorClear.Color[3] = 1.f;
   ComPtr<ID3D12Resource> color, depthTarget;
   Check(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &desc,
                                         D3D12_RESOURCE_STATE_RENDER_TARGET,
                                         &colorClear, IID_PPV_ARGS(&color)),
         "MSAA HDR target failed");
   desc.Format = DXGI_FORMAT_D32_FLOAT;
   desc.Flags = D3D12_RESOURCE_FLAG_ALLOW_DEPTH_STENCIL;
   D3D12_CLEAR_VALUE depthClear{};
   depthClear.Format = desc.Format;
   depthClear.DepthStencil.Depth = 1.f;
   Check(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &desc,
                                         D3D12_RESOURCE_STATE_DEPTH_WRITE,
                                         &depthClear,
                                         IID_PPV_ARGS(&depthTarget)),
         "MSAA depth target failed");
   msaaHdrSceneColor = std::move(color);
   msaaDepth = std::move(depthTarget);
   desc.Format=DXGI_FORMAT_R16G16B16A16_FLOAT;
   desc.Flags=D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET;
   Check(device->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&desc,D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE,&colorClear,IID_PPV_ARGS(&msaaAtmosphereSceneSnapshot)),"MSAA atmosphere scene snapshot failed");
   D3D12_CPU_DESCRIPTOR_HANDLE rtv =
       rtvHeap->GetCPUDescriptorHandleForHeapStart();
   rtv.ptr += SIZE_T(Frames * 2 + 3) * rtvStep;
   D3D12_RENDER_TARGET_VIEW_DESC rtvDesc{};
   rtvDesc.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
   rtvDesc.ViewDimension = D3D12_RTV_DIMENSION_TEXTURE2DMS;
    device->CreateRenderTargetView(msaaHdrSceneColor.Get(), &rtvDesc, rtv);
    D3D12_SHADER_RESOURCE_VIEW_DESC srvDesc{};
    srvDesc.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
    srvDesc.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2DMS;
    srvDesc.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    D3D12_CPU_DESCRIPTOR_HANDLE srv =
        textureHeap->GetCPUDescriptorHandleForHeapStart();
    srv.ptr += SIZE_T(MsaaHdrSceneSrvDescriptor3D) * textureStep;
    device->CreateShaderResourceView(msaaHdrSceneColor.Get(), &srvDesc, srv);
   D3D12_CPU_DESCRIPTOR_HANDLE dsv =
       dsvHeap->GetCPUDescriptorHandleForHeapStart();
   dsv.ptr += SIZE_T(2) * device->GetDescriptorHandleIncrementSize(
                              D3D12_DESCRIPTOR_HEAP_TYPE_DSV);
   D3D12_DEPTH_STENCIL_VIEW_DESC dsvDesc{};
   dsvDesc.Format = DXGI_FORMAT_D32_FLOAT;
   dsvDesc.ViewDimension = D3D12_DSV_DIMENSION_TEXTURE2DMS;
   device->CreateDepthStencilView(msaaDepth.Get(), &dsvDesc, dsv);
   stats.multisampleResidentBytes = size_t(width) * height * 80;
   stats.multisampleEnabled = true;
   stats.multisampleCount = 4;
    ++stats.multisampleAllocations;
  }
  void RecordDeterministicHdrResolve(D3D12_CPU_DESCRIPTOR_HANDLE destinationRtv) {
    ID3D12DescriptorHeap* heaps[] = {textureHeap.Get()};
    list->SetDescriptorHeaps(1, heaps);
    list->SetGraphicsRootSignature(deterministicResolveRoot.Get());
    D3D12_GPU_DESCRIPTOR_HANDLE source =
        textureHeap->GetGPUDescriptorHandleForHeapStart();
    source.ptr += UINT64(MsaaHdrSceneSrvDescriptor3D) * textureStep;
    list->SetGraphicsRootDescriptorTable(0, source);
    list->OMSetRenderTargets(1, &destinationRtv, FALSE, nullptr);
    const D3D12_VIEWPORT viewport{0.f, 0.f, float(width), float(height), 0.f, 1.f};
    const D3D12_RECT scissor{0, 0, LONG(width), LONG(height)};
    list->RSSetViewports(1, &viewport);
    list->RSSetScissorRects(1, &scissor);
    list->SetPipelineState(deterministicResolvePipeline.Get());
    list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    list->DrawInstanced(3, 1, 0, 0);
  }
