void D3D12Renderer::DestroySkinnedMesh(SkinnedMeshHandle3D handle){if(!impl_||!handle)return;
    auto& d=*impl_;
    auto found=d.residentSkinnedMeshes.find(handle.value);
    if(found==d.residentSkinnedMeshes.end()||found->second.resourceIdentity!=handle.resourceIdentity)return;
    if(found->second.references>1){--found->second.references;
    --d.stats.residentSkinnedMeshReferences;
    return;
    }d.SubmitMeshUploadBatch();
    d.PrepareGpuRetirement();
    RetiredGpuResources3D retired{};
    retired.resources[0]=std::move(found->second.buffer);
    retired.bytes=found->second.bytes;
    const auto cached=d.skinnedMeshCache.find(found->second.cacheKey);
    if(cached!=d.skinnedMeshCache.end()&&cached->second==handle.value)d.skinnedMeshCache.erase(cached);
    d.stats.residentMeshBytes-=retired.bytes;
    --d.stats.residentMeshResources;
    d.stats.residentSkinnedMeshBytes-=retired.bytes;
    --d.stats.residentSkinnedMeshes;
    --d.stats.residentSkinnedMeshReferences;
    ++d.stats.skinnedMeshReleases;
    d.residentSkinnedMeshes.erase(found);
    d.RetireGpuResources(std::move(retired));
    }

